CREATE FUNCTION public.garantie_klant_zoeken(p_query text) RETURNS SETOF public.contacts LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT c.* FROM public.contacts c WHERE c.type IN('b2b','b2c') AND (concat_ws(' ',c.first_name,c.last_name,c.company_name,c.phone,c.email) ILIKE '%'||trim(p_query)||'%' OR EXISTS(SELECT 1 FROM public.vehicles v WHERE v.customer_id=c.id AND length(regexp_replace(p_query,'[^A-Za-z0-9]','','g'))>=3 AND upper(regexp_replace(coalesce(v.license_number,''),'[^A-Za-z0-9]','','g')) LIKE '%'||upper(regexp_replace(p_query,'[^A-Za-z0-9]','','g'))||'%')) ORDER BY c.created_at DESC LIMIT 50 $$;
REVOKE ALL ON FUNCTION public.garantie_klant_zoeken(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.garantie_klant_zoeken(text) TO authenticated;